import{_ as e,o as a,c as r,a5 as o}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"彩色宝石分级（hue / tone / saturation）","description":"","frontmatter":{"title":"彩色宝石分级（hue / tone / saturation）","grading":"colored-stones"},"headers":[],"relativePath":"zh/grading/colored-stones.md","filePath":"zh/grading/colored-stones.md","lastUpdated":1789155237000}'),d={name:"zh/grading/colored-stones.md"};function i(n,t,l,h,s,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="彩色宝石分级-hue-tone-saturation" tabindex="-1">彩色宝石分级（hue / tone / saturation） <a class="header-anchor" href="#彩色宝石分级-hue-tone-saturation" aria-label="Permalink to &quot;彩色宝石分级（hue / tone / saturation）&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>彩色宝石不像钻石有标准化 4C，而是用三维度描述颜色——hue（色相）、tone （色调明暗）、saturation（饱和度）。许多实验室会使用这组描述维度， 但具体报告术语与阈值可能不同。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>hue：色相在色环上的位置；理想宝石色通常纯度高（无偏色）。</li><li>tone：色调明暗，从 very light 到 very dark 六档；常见优选区间会因品种而异。</li><li>saturation：色彩饱和度，灰/棕色调降级；vivid / strong 最佳。</li><li>颜色通常是重要价格因素，但切工、净度、耐久性、处理和供需同样会改变价值。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>等级</th><th>备注</th></tr></thead><tbody><tr><td>ruby</td><td>vivid red, medium tone</td><td>鸽血红</td></tr><tr><td>emerald</td><td>vivid green, slightly bluish</td><td>—</td></tr><tr><td>sapphire</td><td>vivid blue, medium-dark</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">分级总览</a>。</em></p>',8)])])}const _=e(d,[["render",i]]);export{m as __pageData,_ as default};
